1	/**
2	 * pyrepr.mjs — Python 3 `repr()` for `bytes` and `str`, plus `print()` semantics.
3	 *
4	 * Faithful ports of:
5	 *   - CPython Objects/bytesobject.c :: bytes_repr()
6	 *   - CPython Objects/unicodeobject.c :: unicode_repr()
7	 *   - CPython Objects/unicodectype.c :: Py_UNICODE_ISPRINTABLE()  (str.isprintable)
8	 *
9	 * Node.js ESM. Zero dependencies: no npm packages and no imports at all — only
10	 * the `process` and `Buffer` globals. Everything is implemented from scratch.
11	 */
12	
13	const BACKSLASH = 0x5c;
14	const SQUOTE = 0x27; // '
15	const DQUOTE = 0x22; // "
16	const TAB = 0x09;
17	const LF = 0x0a;
18	const CR = 0x0d;
19	const SPACE = 0x20;
20	const DEL = 0x7f;
21	
22	/** Lowercase two-digit hex, e.g. 10 -> "0a". */
23	const hex2 = (n) => n.toString(16).padStart(2, '0');
24	/** Lowercase hex padded to `width` digits. */
25	const hexPad = (n, width) => n.toString(16).padStart(width, '0');
26	
27	// ---------------------------------------------------------------------------
28	// str.isprintable()
29	// ---------------------------------------------------------------------------
30	
31	/**
32	 * CPython's makeunicodedata.py marks a codepoint printable as:
33	 *
34	 *   printable = NOT in general categories Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs
35	 *               EXCEPT that U+0020 SPACE is printable.
36	 *
37	 * We express that as a single precompiled RegExp over Unicode property escapes
38	 * rather than a generated lookup table. `\p{Cn}` (General_Category=Unassigned)
39	 * is supported by V8; `\P{Assigned}` is the documented equivalent and is used
40	 * as a fallback for engines that reject the `Cn` alias.
41	 *
42	 * CAVEAT — Unicode database version. Binding to `\p{...}` means we inherit the
43	 * host engine's UCD, exactly as CPython inherits the UCD it was built against.
44	 * Node 18.19 / ICU 74 is UCD 15.1; CPython 3.12 is UCD 15.0. An exhaustive
45	 * sweep of all 1114112 codepoints found the two disagree on precisely the 627
46	 * codepoints that Unicode 15.1 newly assigned, and nowhere else:
47	 *   U+2FFC..U+2FFF, U+31EF, U+2EBF0..U+2EE5D   (Cn in 15.0, assigned in 15.1)
48	 * CPython 3.13+ ships UCD 15.1 and agrees with us on all of them.
49	 */
50	const NONPRINTABLE_RE = (() => {
51	  const props = ['Cc', 'Cf', 'Cs', 'Co', 'Cn', 'Zl', 'Zp', 'Zs'];
52	  try {
53	    return new RegExp(`^[${props.map((p) => `\\p{${p}}`).join('')}]$`, 'u');
54	  } catch {
55	    // Older engines may not accept the `Cn` alias; `\P{Assigned}` is identical
56	    // in meaning (everything with General_Category=Unassigned).
57	    const rest = props.filter((p) => p !== 'Cn').map((p) => `\\p{${p}}`).join('');
58	    return new RegExp(`^[${rest}\\P{Assigned}]$`, 'u');
59	  }
60	})();
61	
62	/**
63	 * Memo for non-ASCII codepoints. Classification is pure, and repr() over a long
64	 * string tends to revisit the same codepoints, so caching keeps us off the
65	 * regex engine in the common case. Populated lazily — no giant static table.
66	 */
67	const printableCache = new Map();
68	
69	/**
70	 * Python's `str.isprintable()` rule, evaluated for a single codepoint.
71	 *
72	 * @param {number} cp - Unicode codepoint (0 .. 0x10FFFF). Lone surrogates
73	 *   (0xD800..0xDFFF) are accepted and reported non-printable, matching CPython,
74	 *   which permits them inside `str`.
75	 * @returns {boolean} true if Python would emit the character literally.
76	 */
77	export function isPrintable(cp) {
78	  // Fast path: printable ASCII, including SPACE (the sole Zs exception).
79	  if (cp >= SPACE && cp < DEL) return true;
80	  // Fast path: C0 controls and DEL are Cc, never printable.
81	  if (cp < SPACE || cp === DEL) return false;
82	
83	  const cached = printableCache.get(cp);
84	  if (cached !== undefined) return cached;
85	
86	  // String.fromCodePoint happily produces a lone surrogate, which `\p{Cs}`
87	  // matches under the /u flag, so no special-casing is required here.
88	  const result = !NONPRINTABLE_RE.test(String.fromCodePoint(cp));
89	  printableCache.set(cp, result);
90	  return result;
91	}
92	
93	// ---------------------------------------------------------------------------
94	// bytes repr
95	// ---------------------------------------------------------------------------
96	
97	/** Coerce the accepted input shapes to a Uint8Array without copying when possible. */
98	function toBytes(bytes) {
99	  if (bytes instanceof Uint8Array) return bytes;
100	  if (bytes instanceof ArrayBuffer) return new Uint8Array(bytes);
101	  if (ArrayBuffer.isView(bytes)) {
102	    return new Uint8Array(bytes.buffer, bytes.byteOffset, bytes.byteLength);
103	  }
104	  if (Array.isArray(bytes)) return Uint8Array.from(bytes);
105	  throw new TypeError('bytesRepr: expected Uint8Array, ArrayBuffer view, or array of 0..255');
106	}
107	
108	/**
109	 * Python 3 `repr()` of a `bytes` object.
110	 *
111	 * @param {Uint8Array|ArrayBuffer|ArrayBufferView|number[]} bytes
112	 * @returns {string} e.g. "b'xn--caf-dma'"
113	 */
114	export function bytesRepr(bytes) {
115	  const buf = toBytes(bytes);
116	
117	  // Quote selection (CPython's "smart quotes"): single quotes by default;
118	  // switch to double quotes only when a ' is present and a " is not.
119	  let hasSquote = false;
120	  let hasDquote = false;
121	  for (let i = 0; i < buf.length; i++) {
122	    if (buf[i] === SQUOTE) hasSquote = true;
123	    else if (buf[i] === DQUOTE) hasDquote = true;
124	  }
125	  const quote = hasSquote && !hasDquote ? DQUOTE : SQUOTE;
126	  const quoteChar = String.fromCharCode(quote);
127	
128	  const out = ['b', quoteChar];
129	  for (let i = 0; i < buf.length; i++) {
130	    const c = buf[i];
131	    // Order matters and mirrors bytes_repr(): quote/backslash first, then the
132	    // three named whitespace escapes, then the generic \xNN range.
133	    if (c === quote || c === BACKSLASH) out.push('\\', String.fromCharCode(c));
134	    else if (c === TAB) out.push('\\t');
135	    else if (c === LF) out.push('\\n');
136	    else if (c === CR) out.push('\\r');
137	    else if (c < SPACE || c >= DEL) out.push('\\x', hex2(c));
138	    else out.push(String.fromCharCode(c));
139	  }
140	  out.push(quoteChar);
141	  return out.join('');
142	}
143	
144	// ---------------------------------------------------------------------------
145	// str repr
146	// ---------------------------------------------------------------------------
147	
148	/**
149	 * Escape a non-printable codepoint the way unicode_repr() does:
150	 * \xNN below 0x100, \uNNNN below 0x10000, \UNNNNNNNN above.
151	 */
152	function escapeCodepoint(cp) {
153	  if (cp < 0x100) return `\\x${hexPad(cp, 2)}`;
154	  if (cp < 0x10000) return `\\u${hexPad(cp, 4)}`;
155	  return `\\U${hexPad(cp, 8)}`;
156	}
157	
158	/**
159	 * Python 3 `repr()` of a `str`.
160	 *
161	 * Iterates by codepoint, so astral characters count as one unit and are emitted
162	 * either literally or as a single `\UNNNNNNNN` escape (never as a surrogate pair).
163	 *
164	 * @param {string} s
165	 * @returns {string}
166	 */
167	export function strRepr(s) {
168	  const str = String(s);
169	
170	  // Quote selection, identical policy to bytes: prefer ', use " only when the
171	  // string contains ' but no ".
172	  const hasSquote = str.includes("'");
173	  const hasDquote = str.includes('"');
174	  const quoteChar = hasSquote && !hasDquote ? '"' : "'";
175	
176	  const out = [quoteChar];
177	  for (const ch of str) {
178	    const cp = ch.codePointAt(0);
179	    if (ch === quoteChar || cp === BACKSLASH) out.push('\\', ch);
180	    else if (cp === TAB) out.push('\\t');
181	    else if (cp === LF) out.push('\\n');
182	    else if (cp === CR) out.push('\\r');
183	    else if (isPrintable(cp)) out.push(ch);
184	    else out.push(escapeCodepoint(cp));
185	  }
186	  out.push(quoteChar);
187	  return out.join('');
188	}
189	
190	// ---------------------------------------------------------------------------
191	// print() semantics
192	// ---------------------------------------------------------------------------
193	
194	/**
195	 * Tracks the tail of the stdout write queue so callers can await a real flush.
196	 * Writable invokes write callbacks in submission order, so awaiting the most
197	 * recent one implies every earlier write has landed too. Node also keeps the
198	 * event loop alive for a pending stdout write, so an ordinary exit is already
199	 * safe; this exists for the explicit `process.exit()` case.
200	 */
201	let pendingFlush = Promise.resolve();
202	
203	/**
204	 * Python's `print(text)`: write `text` followed by a newline to stdout as UTF-8.
205	 *
206	 * @param {string} text
207	 */
208	export function printLine(text) {
209	  const chunk = Buffer.from(`${text}\n`, 'utf8');
210	  pendingFlush = new Promise((resolve) => {
211	    // The write callback fires once the chunk has been handed to the OS, which
212	    // is what "flushed" means for a pipe, a file, or a TTY alike. It also fires
213	    // after a drain when the stream is backpressured, so the `false` return
214	    // needs no separate handling. Discard the callback's error argument: this
215	    // promise signals completion only.
216	    process.stdout.write(chunk, () => resolve());
217	  });
218	}
219	
220	/**
221	 * Resolves once everything handed to {@link printLine} has reached the OS.
222	 * Await this before calling `process.exit()`, which otherwise truncates
223	 * asynchronous stdout (pipes and sockets).
224	 *
225	 * @returns {Promise<void>}
226	 */
227	export async function flushStdout() {
228	  await pendingFlush;
229	}
