1	/**
2	 * pyrepr-selftest.mjs — self-test for /tmp/wf/pyrepr.mjs
3	 *
4	 * Runs a fixed set of golden assertions, then (when a local python3 exists)
5	 * a differential fuzz against real CPython repr() for both str and bytes.
6	 *
7	 *   node /tmp/wf/pyrepr-selftest.mjs
8	 */
9	
10	import { spawnSync } from 'node:child_process';
11	import { bytesRepr, strRepr, isPrintable } from './pyrepr.mjs';
12	
13	let passed = 0;
14	const failures = [];
15	
16	function eq(label, actual, expected) {
17	  if (actual === expected) {
18	    passed++;
19	  } else {
20	    failures.push(`${label}\n    expected: ${JSON.stringify(expected)}\n    actual:   ${JSON.stringify(actual)}`);
21	  }
22	}
23	
24	const enc = new TextEncoder();
25	const b = (s) => enc.encode(s);
26	
27	// ---------------------------------------------------------------------------
28	// 1. Golden cases named in the task
29	// ---------------------------------------------------------------------------
30	
31	// repr('ab‌cd') -> 'ab‌cd' with the ZWNJ escaped as backslash-u-2-0-0-c.
32	// Built character-by-character so the expectation cannot itself contain a real ZWNJ.
33	const ZWNJ_EXPECTED = ["'", 'a', 'b', '\\', 'u', '2', '0', '0', 'c', 'c', 'd', "'"].join('');
34	eq("strRepr('ab<ZWNJ>cd')", strRepr('ab‌cd'), ZWNJ_EXPECTED);
35	
36	// Devanagari stays literal, ZWNJ is escaped.
37	eq(
38	  "strRepr('\\u0928<ZWNJ>\\u093f')",
39	  strRepr('न‌ि'),
40	  "'न" + '\\u200c' + "ि'",
41	);
42	
43	// bytes repr of an A-label.
44	eq("bytesRepr(b'xn--caf-dma')", bytesRepr(b('xn--caf-dma')), "b'xn--caf-dma'");
45	
46	// ---------------------------------------------------------------------------
47	// 2. isPrintable spot checks
48	// ---------------------------------------------------------------------------
49	
50	const printableChecks = [
51	  [0x20, true, 'SPACE is the one printable Zs'],
52	  [0x41, true, 'A'],
53	  [0x7e, true, '~'],
54	  [0x00, false, 'NUL (Cc)'],
55	  [0x09, false, 'TAB (Cc)'],
56	  [0x1f, false, 'US (Cc)'],
57	  [0x7f, false, 'DEL (Cc)'],
58	  [0x80, false, 'C1 control (Cc)'],
59	  [0x9f, false, 'C1 control (Cc)'],
60	  [0xa0, false, 'NBSP (Zs)'],
61	  [0xad, false, 'SOFT HYPHEN (Cf)'],
62	  [0x200c, false, 'ZWNJ (Cf)'],
63	  [0x2028, false, 'LINE SEPARATOR (Zl)'],
64	  [0x2029, false, 'PARAGRAPH SEPARATOR (Zp)'],
65	  [0x3000, false, 'IDEOGRAPHIC SPACE (Zs)'],
66	  [0xd800, false, 'lone high surrogate (Cs)'],
67	  [0xdfff, false, 'lone low surrogate (Cs)'],
68	  [0xe000, false, 'private use (Co)'],
69	  [0x0378, false, 'unassigned (Cn)'],
70	  [0x0928, true, 'DEVANAGARI NA'],
71	  [0x093f, true, 'DEVANAGARI VOWEL SIGN I (Mc)'],
72	  [0x0301, true, 'COMBINING ACUTE (Mn) is printable in Python'],
73	  [0x1f600, true, 'emoji (So)'],
74	  [0xe0001, false, 'LANGUAGE TAG (Cf, astral)'],
75	  [0x10ffff, false, 'noncharacter (Cn)'],
76	];
77	for (const [cp, want, why] of printableChecks) {
78	  eq(`isPrintable(U+${cp.toString(16).toUpperCase().padStart(4, '0')}) ${why}`, isPrintable(cp), want);
79	}
80	
81	// ---------------------------------------------------------------------------
82	// 3. Quote selection + escaping, both types
83	// ---------------------------------------------------------------------------
84	
85	eq('strRepr empty', strRepr(''), "''");
86	eq('strRepr plain', strRepr('abc'), "'abc'");
87	eq('strRepr squote only -> double quotes', strRepr("it's"), '"it\'s"');
88	eq('strRepr dquote only -> single quotes', strRepr('say "hi"'), '\'say "hi"\'');
89	eq('strRepr both quotes -> single, escape squote', strRepr('it\'s "x"'), '\'it\\\'s "x"\'');
90	eq('strRepr backslash', strRepr('a\\b'), "'a\\\\b'");
91	eq('strRepr tab/nl/cr', strRepr('a\tb\nc\rd'), "'a\\tb\\nc\\rd'");
92	eq('strRepr other C0 -> \\xNN', strRepr('\x00\x01\x1f'), "'\\x00\\x01\\x1f'");
93	eq('strRepr DEL + C1', strRepr('\x7f\x85'), "'\\x7f\\x85'");
94	eq('strRepr NBSP', strRepr(' '), "'\\xa0'");
95	eq('strRepr astral printable stays literal', strRepr('\u{1f600}'), "'\u{1f600}'");
96	eq('strRepr astral non-printable -> \\U', strRepr('\u{e0001}'), "'\\U000e0001'");
97	eq('strRepr lone surrogate -> \\uNNNN', strRepr('\ud800'), "'\\ud800'");
98	eq('strRepr non-ASCII printable literal', strRepr('café'), "'café'");
99	
100	eq('bytesRepr empty', bytesRepr(new Uint8Array(0)), "b''");
101	eq('bytesRepr squote only -> double quotes', bytesRepr(b("it's")), 'b"it\'s"');
102	eq('bytesRepr dquote only -> single quotes', bytesRepr(b('say "hi"')), 'b\'say "hi"\'');
103	eq('bytesRepr both quotes -> single, escape squote', bytesRepr(b('it\'s "x"')), 'b\'it\\\'s "x"\'');
104	eq('bytesRepr backslash', bytesRepr(b('a\\b')), "b'a\\\\b'");
105	eq('bytesRepr tab/nl/cr', bytesRepr(b('a\tb\nc\rd')), "b'a\\tb\\nc\\rd'");
106	eq('bytesRepr high bytes', bytesRepr([0x00, 0x1f, 0x7e, 0x7f, 0x80, 0xff]), "b'\\x00\\x1f~\\x7f\\x80\\xff'");
107	eq('bytesRepr utf8 of café', bytesRepr(b('café')), "b'caf\\xc3\\xa9'");
108	eq('bytesRepr accepts plain array', bytesRepr([104, 105]), "b'hi'");
109	
110	// ---------------------------------------------------------------------------
111	// 4. Differential fuzz against real CPython
112	// ---------------------------------------------------------------------------
113	
114	const PY_DRIVER = `
115	import sys, json
116	data = json.load(sys.stdin)
117	out = []
118	for kind, payload in data:
119	    if kind == 's':
120	        out.append(repr(''.join(chr(c) for c in payload)))
121	    else:
122	        out.append(repr(bytes(payload)))
123	print(json.dumps(out))
124	`;
125	
126	/**
127	 * Codepoints newly assigned in Unicode 15.1. A CPython built against UCD 15.0
128	 * (i.e. 3.12 and earlier) calls these non-printable; Node's ICU 74 is UCD 15.1
129	 * and calls them printable. Disagreement here is host-UCD skew, not a defect,
130	 * so the differential pass reports it separately instead of failing.
131	 */
132	const UCD_151_ADDITIONS = [[0x2ffc, 0x2fff], [0x31ef, 0x31ef], [0x2ebf0, 0x2ee5d]];
133	const isUcdSkew = (cp) => UCD_151_ADDITIONS.some(([lo, hi]) => cp >= lo && cp <= hi);
134	
135	function pythonReprs(cases) {
136	  const r = spawnSync('python3', ['-c', PY_DRIVER], {
137	    input: JSON.stringify(cases),
138	    encoding: 'utf8',
139	    maxBuffer: 64 * 1024 * 1024,
140	  });
141	  if (r.status !== 0) return null;
142	  return JSON.parse(r.stdout);
143	}
144	
145	/** Build a JS string from an array of codepoints (surrogates included). */
146	const fromCps = (cps) => cps.map((c) => String.fromCodePoint(c)).join('');
147	
148	function runDifferential() {
149	  const probe = spawnSync('python3', ['-c', 'print(1)'], { encoding: 'utf8' });
150	  if (probe.status !== 0) {
151	    console.log('  (skipped: no local python3)');
152	    return;
153	  }
154	  const ver = spawnSync('python3', ['-c', 'import sys,unicodedata;print(sys.version.split()[0], unicodedata.unidata_version)'], { encoding: 'utf8' }).stdout.trim();
155	  console.log(`  CPython ${ver}   |   Node ${process.versions.node} ICU ${process.versions.icu} Unicode ${process.versions.unicode}`);
156	
157	  const cases = [];
158	
159	  // (a) Every codepoint in the BMP plus a stride through the astral planes,
160	  //     one codepoint per str case. This is the real test of isPrintable().
161	  for (let cp = 0; cp <= 0xffff; cp++) cases.push(['s', [cp]]);
162	  for (let cp = 0x10000; cp <= 0x10ffff; cp += 7) cases.push(['s', [cp]]);
163	
164	  // (b) Every single byte value as a 1-byte bytes object, plus all 2-byte
165	  //     combinations of the "interesting" bytes (quotes, escapes, boundaries).
166	  for (let v = 0; v <= 0xff; v++) cases.push(['b', [v]]);
167	  const interesting = [0x00, 0x09, 0x0a, 0x0d, 0x1f, 0x20, 0x22, 0x27, 0x5c, 0x7e, 0x7f, 0x80, 0xff];
168	  for (const x of interesting) for (const y of interesting) cases.push(['b', [x, y]]);
169	
170	  // (c) Random multi-codepoint strings, weighted toward escape-triggering chars.
171	  let seed = 0x2f6e2b1;
172	  const rnd = () => {
173	    // xorshift32, so the corpus is deterministic across runs.
174	    seed ^= seed << 13; seed >>>= 0;
175	    seed ^= seed >>> 17;
176	    seed ^= seed << 5; seed >>>= 0;
177	    return seed / 0x100000000;
178	  };
179	  const pool = [0x27, 0x22, 0x5c, 0x09, 0x0a, 0x0d, 0x20, 0x41, 0xa0, 0xad, 0x200c, 0x2028, 0x3000, 0x0928, 0x093f, 0xd800, 0xe000, 0x1f600, 0xe0001];
180	  for (let i = 0; i < 4000; i++) {
181	    const len = 1 + Math.floor(rnd() * 8);
182	    const cps = [];
183	    for (let j = 0; j < len; j++) {
184	      cps.push(rnd() < 0.7 ? pool[Math.floor(rnd() * pool.length)] : Math.floor(rnd() * 0x110000));
185	    }
186	    cases.push(['s', cps]);
187	  }
188	  // (d) Random byte strings.
189	  for (let i = 0; i < 2000; i++) {
190	    const len = 1 + Math.floor(rnd() * 10);
191	    const bytes = [];
192	    for (let j = 0; j < len; j++) {
193	      bytes.push(rnd() < 0.5 ? interesting[Math.floor(rnd() * interesting.length)] : Math.floor(rnd() * 256));
194	    }
195	    cases.push(['b', bytes]);
196	  }
197	
198	  // Chunk so we never hand python an unreasonable stdin blob.
199	  const CHUNK = 20000;
200	  let diffs = 0;
201	  let skew = 0;
202	  const samples = [];
203	  for (let start = 0; start < cases.length; start += CHUNK) {
204	    const slice = cases.slice(start, start + CHUNK);
205	    const expected = pythonReprs(slice);
206	    if (!expected) {
207	      failures.push('differential: python3 driver failed');
208	      return;
209	    }
210	    for (let i = 0; i < slice.length; i++) {
211	      const [kind, payload] = slice[i];
212	      const got = kind === 's' ? strRepr(fromCps(payload)) : bytesRepr(payload);
213	      if (got !== expected[i]) {
214	        // If any codepoint in the case falls in the 15.1 delta, the divergence
215	        // is host-UCD skew rather than a defect in this port.
216	        if (kind === 's' && payload.some(isUcdSkew)) {
217	          skew++;
218	          continue;
219	        }
220	        diffs++;
221	        if (samples.length < 25) {
222	          samples.push(`    ${kind} ${JSON.stringify(payload.map((c) => 'U+' + c.toString(16)))} py=${expected[i]} js=${got}`);
223	        }
224	      } else {
225	        passed++;
226	      }
227	    }
228	  }
229	  console.log(`  differential cases: ${cases.length}, real mismatches: ${diffs}, UCD-15.1-skew: ${skew}`);
230	  if (diffs) failures.push(`differential mismatches: ${diffs}\n${samples.join('\n')}`);
231	
232	  // Exhaustive isPrintable() sweep over every codepoint, straight against
233	  // CPython's str.isprintable(). This is the strongest check in the suite.
234	  const SWEEP_PY = `
235	import sys
236	lo, hi = int(sys.argv[1]), int(sys.argv[2])
237	sys.stdout.write(''.join('1' if chr(cp).isprintable() else '0' for cp in range(lo, hi)))
238	`;
239	  let sweepBad = 0;
240	  let sweepSkew = 0;
241	  for (let lo = 0; lo < 0x110000; lo += 0x8000) {
242	    const hi = Math.min(lo + 0x8000, 0x110000);
243	    const r = spawnSync('python3', ['-c', SWEEP_PY, String(lo), String(hi)], { encoding: 'utf8', maxBuffer: 1 << 28 });
244	    if (r.status !== 0) { failures.push('isPrintable sweep: python3 driver failed'); return; }
245	    for (let i = 0; i < hi - lo; i++) {
246	      const cp = lo + i;
247	      if ((r.stdout[i] === '1') !== isPrintable(cp)) {
248	        if (isUcdSkew(cp)) sweepSkew++;
249	        else { sweepBad++; if (samples.length < 40) samples.push(`    isPrintable U+${cp.toString(16)}`); }
250	      } else passed++;
251	    }
