/**
 * Python's `str.isprintable()` rule, evaluated for a single codepoint.
 *
 * @param {number} cp - Unicode codepoint (0 .. 0x10FFFF). Lone surrogates
 *   (0xD800..0xDFFF) are accepted and reported non-printable, matching CPython,
 *   which permits them inside `str`.
 * @returns {boolean} true if Python would emit the character literally.
 */
export function isPrintable(cp) {
  // Validate up front. Without this the ASCII fast paths below silently accept
  // a negative or fractional argument (isPrintable(-1) -> false,
  // isPrintable(32.5) -> true) while 0x110000 threw from String.fromCodePoint,
  // which is an inconsistent contract. CPython's chr() raises for all of them.
  if (!Number.isInteger(cp) || cp < 0 || cp > 0x10ffff) {
    throw new RangeError(`isPrintable: codepoint not in range(0x110000): ${String(cp)}`);
  }
  // Fast path: printable ASCII, including SPACE (the sole Zs exception).
  if (cp >= SPACE && cp < DEL) return true;
  // Fast path: C0 controls and DEL are Cc, never printable.
  if (cp < SPACE || cp === DEL) return false;

  const cached = printableCache.get(cp);
  if (cached !== undefined) return cached;

  // String.fromCodePoint happily produces a lone surrogate, which `\p{Cs}`
  // matches under the /u flag, so no special-casing is required here.
  const result = !NONPRINTABLE_RE.test(String.fromCodePoint(cp));
  printableCache.set(cp, result);
  return result;
}

