function toBytes(bytes) {
  if (bytes instanceof Uint8Array) return bytes;
  if (bytes instanceof ArrayBuffer) return new Uint8Array(bytes);
  if (ArrayBuffer.isView(bytes)) {
    return new Uint8Array(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  }
  if (Array.isArray(bytes)) {
    // Validate before converting: Uint8Array.from() silently coerces out-of-
    // contract elements (256 -> 0, -1 -> 255, 1.5 -> 1, 'a' -> 0), which would
    // emit a plausible-looking but wrong repr. Python's bytes() raises instead.
    for (let i = 0; i < bytes.length; i++) {
      const v = bytes[i];
      if (!Number.isInteger(v) || v < 0 || v > 255) {
        throw new RangeError(`bytesRepr: element ${i} is not an integer in 0..255: ${String(v)}`);
      }
    }
    return Uint8Array.from(bytes);
